int8_t parse_login(const char json[], char user_buffer[], char password_buffer[], const uint32_t buffer_length) {
	int8_t return_code = 0;

	cJSON *root = cJSON_Parse(json);

	cJSON *user_json = cJSON_GetObjectItemCaseSensitive(root, "user");
	if (!cJSON_IsString(user_json)) {
		return_code = 0;
		goto cleanup;
	}
	uint32_t user_length = strlen(user_json->valuestring) + sizeof("");
	if (user_length > buffer_length) {
		return_code = -1;
		goto cleanup;
	}

	cJSON *password_json = cJSON_GetObjectItemCaseSensitive(root, "password");
	if (!cJSON_IsString(password_json)) {
		return_code = 0;
		goto cleanup;
	}
	uint32_t password_length = strlen(password_json->valuestring) + sizeof("");
	if (password_length > buffer_length) {
		return_code = -1;
		goto cleanup;
	}

	//now copy the login and password
	if ((user_buffer == NULL) || (password_buffer == NULL)) {
		return_code = -1;
		goto cleanup;
	}
	memcpy(user_buffer, user_json->valuestring, user_length);
	memcpy(password_buffer, password_json->valuestring, password_length);
	return_code = user_length + password_length;

cleanup:
	cJSON_Delete(root);
	return return_code;
}

